constraints:
1 ≤ N ≤ 10^{9}

expected time complexity: O(1)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def countBits(self, n: int) -> int:
		k = 1
		su = 0
		while n // 2 ** (k - 1) > 0:
			d = n % 2 ** k
			rep = n // 2 ** k
			rep = rep * 2 ** (k - 1)
			if d + 1 - 2 ** (k - 1) > 0:
				su = su + rep + (d + 1 - 2 ** (k - 1))
			else:
				su += rep
			k += 1
		return su
